class Solution:
    def queensAttacktheKing(self, queens: List[List[int]], king: List[int]) -> List[List[int]]:
        qs = set(map(tuple, queens))
        res = []
        for x, y in queens:
            dx, dy = king[0] - x, king[1] - y
            if dx != 0 and dy != 0 and abs(dx) != abs(dy):
                continue
            sx = (dx > 0) - (dx < 0)
            sy = (dy > 0) - (dy < 0)
            cx, cy = x + sx, y + sy
            while (cx, cy) != (king[0], king[1]):
                if (cx, cy) in qs:
                    break
                cx += sx
                cy += sy
            else:
                res.append([x, y])
        return res

