class Solution {
public:
    vector<vector<int>> queensAttacktheKing(vector<vector<int>>& queens, vector<int>& king) {
        set<pair<int,int>> qs;
        for (auto& q : queens) qs.insert({q[0], q[1]});
        vector<vector<int>> res;
        for (auto& q : queens) {
            int dx = king[0] - q[0], dy = king[1] - q[1];
            if (dx != 0 && dy != 0 && abs(dx) != abs(dy)) continue;
            int sx = (dx > 0) - (dx < 0), sy = (dy > 0) - (dy < 0);
            int cx = q[0] + sx, cy = q[1] + sy;
            bool ok = true;
            while (cx != king[0] || cy != king[1]) {
                if (qs.count({cx, cy})) { ok = false; break; }
                cx += sx; cy += sy;
            }
            if (ok) res.push_back(q);
        }
        return res;
    }
};

