class Solution {
    public List<List<Integer>> queensAttacktheKing(int[][] queens, int[] king) {
        Set<Long> qs = new HashSet<>();
        for (int[] q : queens) qs.add(((long) q[0] << 3) | q[1]);
        List<List<Integer>> res = new ArrayList<>();
        for (int[] q : queens) {
            int dx = king[0] - q[0], dy = king[1] - q[1];
            if (dx != 0 && dy != 0 && Math.abs(dx) != Math.abs(dy)) continue;
            int sx = Integer.signum(dx), sy = Integer.signum(dy);
            int cx = q[0] + sx, cy = q[1] + sy;
            boolean ok = true;
            while (cx != king[0] || cy != king[1]) {
                if (qs.contains(((long) cx << 3) | cy)) { ok = false; break; }
                cx += sx; cy += sy;
            }
            if (ok) res.add(Arrays.asList(q[0], q[1]));
        }
        return res;
    }
}

