class Solution:
    def queensAttacktheKing(self, queens: List[List[int]], king: List[int]) -> List[List[int]]:
        qs = {(x, y) for x, y in queens}
        res = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                r, c = king[0] + dr, king[1] + dc
                while 0 <= r < 8 and 0 <= c < 8:
                    if (r, c) in qs:
                        res.append([r, c])
                        break
                    r += dr
                    c += dc
        return res

